Here is the root cause:
The code assumed that page table entries (PTE, PMD, PUD, P4D) are always allocated from page-aligned memory (struct page aligned), but on architectures like powerpc with 64KB page size, these tables (e.g., PUD table of size 4096) come from a slab cache and are not necessarily page-aligned. Using page_to_virt(pXd_page(*pXd)) to derive the start address of the table produced an incorrect pointer, causing a double free when KASAN attempted to free the same slab object.

Here is the patch:

 static void kasan_free_pte(pte_t *pte_start, pmd_t *pmd)
 {
 	pte_t *pte;
 	int i;

 	for (i = 0; i < PTRS_PER_PTE; i++) {
 		pte = pte_start + i;
 		if (!pte_none(ptep_get(pte)))
 			return;
 	}

-	pte_free_kernel(&init_mm, (pte_t *)page_to_virt(pmd_page(*pmd)));
+	pte_free_kernel(&init_mm, pte_start);
 	pmd_clear(pmd);
 }

 static void kasan_free_pmd(pmd_t *pmd_start, pud_t *pud)
 {
 	pmd_t *pmd;
 	int i;

 	for (i = 0; i < PTRS_PER_PMD; i++) {
 		pmd = pmd_start + i;
 		if (!pmd_none(*pmd))
 			return;
 	}

-	pmd_free(&init_mm, (pmd_t *)page_to_virt(pud_page(*pud)));
+	pmd_free(&init_mm, pmd_start);
 	pud_clear(pud);
 }

 static void kasan_free_pud(pud_t *pud_start, p4d_t *p4d)
 {
 	pud_t *pud;
 	int i;

 	for (i = 0; i < PTRS_PER_PUD; i++) {
 		pud = pud_start + i;
 		if (!pud_none(*pud))
 			return;
 	}

-	pud_free(&init_mm, (pud_t *)page_to_virt(p4d_page(*p4d)));
+	pud_free(&init_mm, pud_start);
 	p4d_clear(p4d);
 }

 static void kasan_free_p4d(p4d_t *p4d_start, pgd_t *pgd)
 {
 	p4d_t *p4d;
 	int i;

 	for (i = 0; i < PTRS_PER_P4D; i++) {
 		p4d = p4d_start + i;
 		if (!p4d_none(*p4d))
 			return;
 	}

-	p4d_free(&init_mm, (p4d_t *)page_to_virt(pgd_page(*pgd)));
+	p4d_free(&init_mm, p4d_start);
 	pgd_clear(pgd);
 }



